style.css:
@-moz-document domain("olx.pl"), domain("olx.ua"), domain("olx.ro"), domain("olx.pt"), domain("olx.bg"), domain("olx.kz") {
/* ============================================================
     OLX ships a Tailwind + design-token frontend. Most colors
     resolve from CSS custom properties on :root, so re-pointing
     those tokens flips the bulk of the UI. The remaining light
     surfaces are emotion (css-*) wrappers with literal hex values
     and hashed class names, so they are handled structurally from
     stable data-testid / id anchors.
     ============================================================ */

  :root {
    color-scheme: dark !important;

    /* ---- Surfaces ---- */
    --color-background-primary: #14181d !important;
    --colorsBackgroundPrimary: #14181d !important;
    --color-background-secondary: #1c2128 !important;
    --colorsBackgroundSecondary: #1c2128 !important;
    --color-background-elevated: #1c2128 !important;
    --colorsBackgroundElevated: #1c2128 !important;
    --color-background-inverse: #0d1117 !important;
    --colorsBackgroundInverse: #0d1117 !important;
    --color-background-disabled: #21262d !important;
    --colorsBackgroundDisabled: #21262d !important;
    --color-background-action-secondary: #21262d !important;
    --colorsBackgroundActionSecondary: #21262d !important;
    --color-background-transparent: #14181d00 !important;
    --colorsBackgroundTransparent: #14181d00 !important;

    /* ---- Foreground / text ---- */
    --color-foreground-primary: #e6edf3 !important;
    --colorsForegroundPrimary: #e6edf3 !important;
    --color-foreground-secondary: #9aa6b0 !important;
    --colorsForegroundSecondary: #9aa6b0 !important;
    --color-foreground-placeholder: #7d8893 !important;
    --color-foreground-on-dark: #e6edf3 !important;

    /* ---- Borders ---- */
    --color-border-subtle: #2d333b !important;
    --colorsBorderSubtle: #2d333b !important;
    --color-border-primary: #2d333b !important;
    --colorsBorderPrimary: #2d333b !important;

    /* ---- OLX accent (raw #23E5DB mint) refined for dark ----
       Keep the recognizable OLX teal/mint identity but pull the
       saturation/lightness down a touch so it sits calmly on the
       near-black palette and dark text on it stays readable. */
    --color-background-accent: #1fcabf !important;
    --colorsBackgroundAccent: #1fcabf !important;
    --color-border-accent: #1fcabf !important;
    --color-background-accent-subtle: #103c3b !important;
    --colorsBackgroundAccentSubtle: #103c3b !important;

    /* ---- Status colors: keep semantic hue, settle onto dark ---- */
    --color-background-status-success: #1f6b54 !important;
    --colorsBackgroundStatusSuccess: #1f6b54 !important;
    --color-background-status-success-subtle: #102a23 !important;
    --colorsBackgroundStatusSuccessSubtle: #102a23 !important;
    --color-background-status-error: #c2402b !important;
    --colorsBackgroundStatusError: #c2402b !important;
    --color-background-status-error-subtle: #3a1b16 !important;
    --colorsBackgroundStatusErrorSubtle: #3a1b16 !important;
    --color-background-status-warning: #d6a425 !important;
    --colorsBackgroundStatusWarning: #d6a425 !important;
    --color-background-status-warning-subtle: #322a12 !important;
    --colorsBackgroundStatusWarningSubtle: #322a12 !important;
  }

  /* ---- Base page ---- */
  html, body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  /* ---- Soften every default light border into a dark hairline ---- */
  * { border-color: #2d333b !important; }

  /* ============================================================
     Header / global nav (OLX dark-teal bar -> deep neutral dark)
     ============================================================ */
  header.app-header,
  header[class*="app-header"] {
    background-color: #0d1117 !important;
    border-bottom: 1px solid #2d333b !important;
  }
  header.app-header a,
  header[class*="app-header"] a,
  header.app-header button { color: #e6edf3 !important; }

  /* The "post new ad" CTA reads as a white pill by default */
  [data-testid="post-new-ad-button"],
  [data-cy="post-new-ad-button"] {
    background-color: #1fcabf !important;
    color: #07232a !important;
    border-color: #1fcabf !important;
  }

  /* Notification + account dropdowns */
  [data-testid="notification-hub-dropdown"],
  [data-cy="notification-hub-wrapper"],
  [class*="menu-dropdown"],
  [role="menu"], [role="listbox"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }

  /* ============================================================
     Main page wrappers — flatten literal light backgrounds.
     Anchored on stable ids/testids so we never touch images.
     #mainContent / #footerContent / #searchmain-container are the
     page-shell wrappers that ship a literal #F2F4F5 / #FFFFFF.
     ============================================================ */
  #hydrate-root,
  #mainContent,
  #footerContent,
  #searchmain-container,
  #searchmain-container > div,
  #searchmain-container > div > div,
  [data-testid="home-page"],
  [data-testid="listing-grid"],
  [data-testid="listing"],
  main, .listing-grid {
    background-color: #14181d !important;
  }
  /* The page-shell light wrappers (#F2F4F5 full-width frames) directly
     under #mainContent carry no stable hook — flatten them to the base. */
  #mainContent > div,
  #mainContent > div > div {
    background-color: transparent !important;
  }
  /* Generic emotion wrappers inside the page shell: make them inherit
     the dark base instead of their hardcoded white/grey. */
  [data-testid="home-page"] > div,
  [data-testid="home-page"] section,
  [data-testid="listing-grid"] > div {
    background-color: transparent !important;
  }

  /* ============================================================
     Search bar (white field on the hero) -> dark input
     ============================================================ */
  [data-testid="search-form"],
  [data-testid="search-autosuggession"],
  form[data-testid="search-form"] > div {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  [data-testid="search-input"],
  [data-cy="search-bar-input"],
  [data-testid="location-search-input"],
  [data-cy="location-search-input"],
  input[type="text"], input[type="search"], textarea, select {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  ::placeholder { color: #7d8893 !important; opacity: 1 !important; }
  [data-testid="search-submit"] {
    background-color: #1fcabf !important;
    color: #07232a !important;
    border-color: #1fcabf !important;
  }
  /* Autosuggest / location dropdown panels */
  [data-testid="search-autosuggession"] [role="listbox"],
  [data-testid="suggestions"], .suggestions,
  [class*="autosuggest"] ul, [class*="dropdown"] ul {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* ============================================================
     Category quick-menu (homepage tiles)
     ============================================================ */
  [data-testid="home-categories-menu"],
  [data-cy="home-categories-menu"],
  [data-testid="home-categories-menu-row"],
  [data-testid^="cat-"], [data-cy^="cat-"] {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  [data-testid^="cat-promo-"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* ============================================================
     Listing / ad cards
     ============================================================ */
  [data-testid="l-card"],
  [data-cy="l-card"] {
    background-color: #1c2128 !important;
    border: 1px solid #2d333b !important;
    border-radius: 8px !important;
  }
  /* Inner emotion wrappers of a card -> transparent so the card bg shows */
  [data-testid="l-card"] > div,
  [data-cy="l-card"] > div,
  [data-testid="l-card"] [class*="css-"]:not(img) {
    background-color: transparent !important;
  }
  /* Image placeholder block inside cards (grey #ECEEEF) — the photo
     wrapper is a plain div under the card link, so target the link's
     image holder generically while leaving the <img> itself alone. */
  [data-testid="l-card"] a > div,
  [data-testid="l-card"] [data-testid="image-container"],
  [data-testid="l-card"] figure,
  [data-testid="l-card"] [class*="image"] {
    background-color: #21262d !important;
  }
  [data-testid="ad-card-title"],
  [data-cy="ad-card-title"] { color: #e6edf3 !important; }
  [data-testid="ad-card-title"] a,
  [data-cy="ad-card-title"] a { color: #e6edf3 !important; }
  [data-testid="ad-price"] { color: #ffffff !important; font-weight: 700 !important; }
  [data-testid="location-date"] { color: #8b949e !important; }

  /* Delivery / promoted / negotiable badges */
  [data-testid="card-delivery-badge"],
  [data-testid="btr-label-wrapper"] {
    background-color: #103c3b !important;
    border-color: #1fcabf !important;
  }
  [data-testid="btr-label-text"] { color: #6fe3da !important; }

  /* Favourite (heart) toggle */
  [data-testid="adAddToFavorites"] { color: #c4cdd6 !important; }

  /* ============================================================
     Top promo / info banner strip (was pale yellow #FFF6D9)
     ============================================================ */
  #banner, #banner > div,
  [data-testid="top-banner-wrapper"],
  [data-testid="cta-banner-click"] {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  [data-testid="banner-btn"], [data-testid="bep-button"] {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* ============================================================
     Search-results page: filters sidebar, sort dropdowns, pills
     ============================================================ */
  [data-testid="listing-filters"],
  [data-testid="filters-container"],
  [data-testid="qsearch-container"],
  [class*="filter"] [role="button"],
  [data-testid="chips-container"] > * {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }
  [data-testid="pagination-wrapper"] a,
  [data-testid="pagination-list"] li {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  [data-testid="pagination-forward"],
  [data-testid="pagination-back"] { color: #e6edf3 !important; }

  /* ============================================================
     Individual offer / item page
     ============================================================ */
  /* Content + sidebar columns -> transparent so the base shows through */
  [data-testid="main"],
  [data-testid="main"] > div,
  [data-testid="aside"],
  [data-testid="aside"] > div,
  [data-testid="ad_description"],
  [data-testid="ad-parameters-container"],
  [data-testid="ad-promotion-actions"] {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  /* Distinct cards within the offer page -> elevated surface */
  [data-testid="ad-action-box"],
  [data-testid="seller_card"],
  [data-testid="map-aside-section"],
  [data-testid="legal-information-accordion"],
  [data-testid="user-profile-link"],
  [data-testid="qa-skeleton-item"],
  [data-testid="ad-card-loader"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  /* Inner emotion wrappers of those cards -> transparent so no white blocks */
  [data-testid="ad-action-box"] > div,
  [data-testid="seller_card"] > div,
  [data-testid="user-profile-link"] > div,
  [data-testid="map-aside-section"] > div {
    background-color: transparent !important;
  }
  /* In-content seller-contact card (white box under main > section) */
  [data-testid="main"] > section > div {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  /* Title + price */
  [data-cy="ad_title"], [data-testid="offer_title"],
  [data-testid="ad-price-container"],
  [data-testid="prices-wrapper"],
  [data-testid="ad-price-container"] h3 {
    color: #e6edf3 !important;
  }
  [data-testid="prices-wrapper"] h3,
  [data-testid="price-label"], [data-testid="ad-price-value"] {
    color: #ffffff !important;
  }
  /* Description + parameter text */
  [data-testid="ad_description"], [data-testid="ad_description"] *,
  [data-testid="ad-parameters-container"] p,
  [data-testid="ad-parameters-container"] li,
  [data-testid="trader-title"], [data-testid="user-profile-user-name"],
  [data-testid="ad-posted-at"] {
    color: #c4cdd6 !important;
  }
  /* Contact / chat / phone buttons */
  [data-testid="ad-contact-message-button"],
  [data-testid="ad-contact-phone"],
  [data-testid="show-phone"],
  [data-testid="phones-container"] button,
  button[data-testid*="contact"] {
    background-color: #1fcabf !important;
    color: #07232a !important;
    border-color: #1fcabf !important;
  }

  /* Image gallery surrounds */
  [data-testid="image-galery-container"],
  [data-testid="ad-photo"],
  [data-testid="gallery"],
  [data-testid="swiper-list"] {
    background-color: #0d1117 !important;
  }

  /* ============================================================
     Login / registration pages (login.olx.<tld> — separate app,
     no design tokens, classic ids: #username / #password / .login-box)
     ============================================================ */
  [data-testid="core-layout"] {
    background-color: #14181d !important;
  }
  .login-box,
  [data-testid="login-form"],
  [data-testid="registration-form"] {
    background-color: #1c2128 !important;
    border: 1px solid #2d333b !important;
    color: #e6edf3 !important;
  }
  /* Social sign-in buttons (white pills) -> elevated dark.
     The testid sits on a wrapper; the white surface is the inner button. */
  [data-testid="facebook-button"], [data-testid="facebook-button"] *,
  [data-testid="apple-button"], [data-testid="apple-button"] *,
  [data-testid="google-button"], [data-testid="google-button"] * {
    background-color: #21262d !important;
    border-color: #2d333b !important;
  }
  [data-testid="facebook-button"], [data-testid="apple-button"],
  [data-testid="google-button"] { color: #e6edf3 !important; }
  /* Email + password fields */
  #username, #password,
  [data-testid="login-form"] input {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  /* Tabs (Sign in / Register) */
  [data-testid="tabs"] { color: #c4cdd6 !important; }
  [data-testid="or-separator"] { color: #8b949e !important; }
  /* Submit button keeps the OLX accent */
  [data-testid="login-submit-button"],
  [data-testid="register-submit-button"],
  button[type="submit"] {
    background-color: #1fcabf !important;
    color: #07232a !important;
    border-color: #1fcabf !important;
  }
  [data-testid="terms-conditions-link"],
  a[href*="login"], a[href*="register"],
  [data-testid="link"], a.link { color: #5fd0c6 !important; }

  /* ============================================================
     Breadcrumbs (literal dark-teal text on the listing/offer pages)
     ============================================================ */
  [data-testid="breadcrumbs"], [data-testid="breadcrumbs"] *,
  nav[aria-label*="readcrumb"] a, [class*="breadcrumb"] a {
    color: #9aa6b0 !important;
  }
  [data-testid="breadcrumbs"] a:hover { color: #e6edf3 !important; }

  /* ============================================================
     Generic links + footer
     ============================================================ */
  a { color: #c4cdd6; }
  a:hover { color: #ffffff !important; }

  footer,
  [data-testid="footer"],
  [class*="footer"] {
    background-color: #0d1117 !important;
    color: #9aa6b0 !important;
    border-top: 1px solid #2d333b !important;
  }
  footer a, [data-testid="footer"] a { color: #9aa6b0 !important; }
  footer a:hover { color: #e6edf3 !important; }

  /* ============================================================
     Scrollbar polish
     ============================================================ */
  ::-webkit-scrollbar { width: 12px; height: 12px; }
  ::-webkit-scrollbar-track { background: #0d1117; }
  ::-webkit-scrollbar-thumb { background: #2d333b; border-radius: 6px; }
  ::-webkit-scrollbar-thumb:hover { background: #3a424c; }
}
